// Minimal argparse-compatible command-line parser (ESM, zero dependencies).
// Mimics Python's argparse for `--name value` / `--name=value` style options
// with `required` support, writing usage/errors to stderr and exiting like
// the original CLI.

import { basename } from 'node:path';

function progName() {
  // argparse derives prog from sys.argv[0]; here we use the script name.
  return basename(process.argv[1] || 'test2.mjs');
}

function usageLine(specs) {
  const parts = ['[-h]'];
  for (const spec of specs) {
    parts.push(spec.required ? `--${spec.name} ${spec.metavar}` : `[--${spec.name} ${spec.metavar}]`);
  }
  return `usage: ${progName()} ${parts.join(' ')}`;
}

function fail(specs, message) {
  process.stderr.write(usageLine(specs) + '\n');
  process.stderr.write(`${progName()}: error: ${message}\n`);
  process.exit(2);
}

/**
 * Parse process.argv according to the given option specs.
 * Each spec: { name: 'key', required: true, metavar: 'KEY' }
 * Returns an object mapping option names to their string values.
 */
export function parseArgs(argv, specs) {
  const args = argv.slice(2);
  const result = {};
  const byName = new Object(null);
  for (const spec of specs) byName[spec.name] = spec;

  for (let i = 0; i < args.length; i++) {
    const token = args[i];
    if (token === '-h' || token === '--help') {
      process.stdout.write(usageLine(specs) + '\n');
      process.exit(0);
    }
    let name = null;
    let value = null;
    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      if (eq !== -1) {
        name = token.slice(2, eq);
        value = token.slice(eq + 1);
      } else {
        name = token.slice(2);
        if (i + 1 < args.length) {
          value = args[++i];
        } else {
          fail(specs, `argument --${name}: expected one argument`);
        }
      }
    } else {
      fail(specs, `unrecognized arguments: ${token}`);
    }
    if (!(name in byName)) {
      fail(specs, `unrecognized arguments: ${token}`);
    }
    result[name] = value;
  }

  const missing = specs.filter((s) => s.required && !(s.name in result));
  if (missing.length > 0) {
    const list = missing.map((s) => `--${s.name}`).join(', ');
    fail(specs, `the following arguments are required: ${list}`);
  }
  return result;
}

