// Bidirectional dictionary reimplementation (ESM, zero dependencies).
// Behavior mirrors the observable interface of Python's bidict for the
// operations used here: construction from key/value pairs and lookup by key,
// raising a KeyError-style error for missing keys. Forward and inverse
// mappings are kept as plain objects.

export class KeyError extends Error {
  constructor(key) {
    super(String(key));
    this.name = 'KeyError';
    this.key = key;
  }
}

export class Bidict {
  constructor(entries) {
    this._forward = Object.create(null);
    this._inverse = Object.create(null);
    if (entries && typeof entries === 'object') {
      for (const [k, v] of Object.entries(entries)) {
        this._forward[k] = v;
        this._inverse[v] = k;
      }
    }
  }

  // Equivalent of b[key] in Python.
  get(key) {
    if (Object.prototype.hasOwnProperty.call(this._forward, key)) {
      return this._forward[key];
    }
    throw new KeyError(key);
  }

  // Inverse lookup, equivalent of b.inverse[value].
  getKey(value) {
    if (Object.prototype.hasOwnProperty.call(this._inverse, value)) {
      return this._inverse[value];
    }
    throw new KeyError(value);
  }
}

export function bidict(entries) {
  return new Bidict(entries);
}

