// Entry test file — Node.js ESM port of /workspace/dataset/bidict/test2.py.
// Usage: node test2.mjs --key <key> --val <val>

import { parseArgs } from './argparse.mjs';
import { bidict, KeyError } from './bidict.mjs';

const args = parseArgs(process.argv, [
  { name: 'key', required: true, metavar: 'KEY' },
  { name: 'val', required: true, metavar: 'VAL' },
]);

// 创建双向字典并访问值
const b = bidict({ a: 1, b: 2 });
let result;
try {
  result = b.get(args.key);
} catch (err) {
  if (err instanceof KeyError) {
    // Mirror Python's unhandled KeyError: traceback to stderr, exit code 1.
    process.stderr.write('Traceback (most recent call last):\n');
    process.stderr.write('  File "test2.py", line 11, in <module>\n');
    process.stderr.write(`KeyError: '${err.key}'\n`);
    process.exit(1);
  }
  throw err;
}
console.log(result);

